(() => {
  const headings = [...document.querySelectorAll('h1,h2,h3')].map(h => h.innerText.trim()).filter(Boolean);
  const free = [...document.querySelectorAll('*')].find(el => el.childElementCount < 12 && /Free plan/i.test(el.innerText) && el.innerText.length < 800);
  const drawer = free ? (free.closest('[class*="drawer"], [class*="panel"], [class*="modal"], aside, [role="dialog"]') || free.parentElement?.parentElement) : null;
  return {
    inner: [window.innerWidth, window.innerHeight],
    visual: window.visualViewport && [window.visualViewport.width, window.visualViewport.height],
    headings: headings.slice(0, 30),
    drawerText: drawer ? drawer.innerText.slice(0, 2500) : (free ? free.innerText.slice(0, 2500) : null),
    drawerRect: drawer ? drawer.getBoundingClientRect().toJSON() : null
  };
})()

(() => {
  function walk(root, acc=[]) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT);
    let n;
    while ((n = walker.nextNode())) {
      if (n.shadowRoot) walk(n.shadowRoot, acc);
      const t = n.innerText && n.innerText.trim();
      if (t && /Free plan|Campaign usage|prepaid/i.test(t) && t.length < 3000 && n.children.length < 40) {
        acc.push({tag: n.tagName, cls: (n.className||'').toString().slice(0,80), text: t.slice(0,1500)});
      }
    }
    return acc;
  }
  const iframes = [...document.querySelectorAll('iframe')].map(f => ({src: f.src, rect: f.getBoundingClientRect().toJSON()}));
  return {iframes, matches: walk(document).slice(0, 8)};
})()

(() => {
  const links = [...document.querySelectorAll('a')].map(a => ({text: (a.innerText||'').trim().slice(0,80), href: a.href})).filter(x => /plan|billing|credit|upgrade|contact|campaign|pricing/i.test(x.text+' '+x.href));
  const el = [...document.querySelectorAll('*')].find(n => n.childElementCount > 0 && n.childElementCount < 20 && /^Your plan usage/i.test((n.innerText||'').trim()) && (n.innerText||'').length < 600);
  if (el) el.scrollIntoView({block:'center'});
  return {links: links.slice(0, 25), planCard: el ? {text: el.innerText, rect: el.getBoundingClientRect().toJSON(), cls: (el.className||'').toString().slice(0,120)} : null};
})()

(() => {
  const nav = [...document.querySelectorAll('nav a, [role=menuitem], a')].map(a => ({text: (a.innerText||a.getAttribute('aria-label')||'').trim().slice(0,60), href: a.href || a.getAttribute('href')})).filter(x => x.href && x.href.startsWith('http'));
  const uniq = [];
  const seen = new Set();
  for (const x of nav) { if (!seen.has(x.href)) { seen.add(x.href); uniq.push(x); } }
  return uniq;
})()

(() => {
  const main = document.querySelector('main') || document.querySelector('.page__content');
  if (main) main.scrollTop = 700;
  const scroller = [...document.querySelectorAll('*')].find(el => el.scrollHeight > el.clientHeight + 80 && el.clientHeight > 400 && getComputedStyle(el).overflowY !== 'visible');
  if (scroller) scroller.scrollTop = Math.min(900, scroller.scrollHeight);
  return {
    main: main && {cls: main.className, scrollTop: main.scrollTop, sh: main.scrollHeight, ch: main.clientHeight},
    scroller: scroller && {cls: (scroller.className||'').toString().slice(0,80), tag: scroller.tagName, scrollTop: scroller.scrollTop, sh: scroller.scrollHeight, ch: scroller.clientHeight}
  };
})()

new Promise(r => {
  const start = Date.now();
  const tick = () => {
    const text = document.body.innerText || '';
    if (/Free|Starter|Business|plan|Choose|Upgrade/i.test(text) && text.length > 800) {
      r({ok:true, title: document.title, len: text.length, snippet: text.slice(0, 2500)});
    } else if (Date.now()-start > 8000) {
      r({ok:false, title: document.title, len: text.length, snippet: text.slice(0, 1500)});
    } else setTimeout(tick, 300);
  };
  tick();
})

(() => {
  const t = document.body.innerText || '';
  return {len: t.length, text: t.slice(0, 3500)};
})()

new Promise(r => {
  const start = Date.now();
  const tick = () => {
    const t = document.body.innerText || '';
    const ready = document.title !== 'Brevo' || t.length > 600;
    if (ready && t.length > 400) r({title: document.title, url: location.href, text: t.slice(0, 2500)});
    else if (Date.now()-start > 10000) r({title: document.title, url: location.href, text: t.slice(0, 1500), timeout: true});
    else setTimeout(tick, 250);
  };
  tick();
})

(() => {
  const cs = getComputedStyle(document.body);
  const h = document.querySelector('h1');
  const hs = h ? getComputedStyle(h) : null;
  const fonts = [...document.fonts].map(f => f.family).filter((v,i,a)=>a.indexOf(v)===i).slice(0,20);
  const root = getComputedStyle(document.documentElement);
  const vars = {};
  for (const sheet of document.styleSheets) {
    try {
      for (const r of sheet.cssRules) {
        if (r.selectorText === ':root' || r.selectorText === 'html') {
          for (const k of r.style) if (k.startsWith('--')) vars[k] = r.style.getPropertyValue(k).trim();
        }
      }
    } catch(e) {}
  }
  return {
    bodyFont: cs.fontFamily,
    bodySize: cs.fontSize,
    bodyBg: cs.backgroundColor,
    h1Font: hs && hs.fontFamily,
    h1Size: hs && hs.fontSize,
    h1Weight: hs && hs.fontWeight,
    fonts: fonts.slice(0, 15),
    cssVars: Object.fromEntries(Object.entries(vars).slice(0, 40))
  };
})()

(() => {
  const vars = {};
  for (const sheet of document.styleSheets) {
    try {
      for (const r of sheet.cssRules) {
        if (r.selectorText === ':root' || r.selectorText === 'html') {
          for (const k of r.style) {
            if (/purple|violet|indigo|lavender|accent|primary/i.test(k)) vars[k] = r.style.getPropertyValue(k).trim();
          }
        }
      }
    } catch(e) {}
  }
  return vars;
})()

