/* App chrome — N3 side-rail + workbench. Tokens stay in design-tokens.css. */

.layout:has(.app-shell) {
  max-width: none;
  margin: 0;
  padding: 0;
}

.app-shell {
  display: grid;
  grid-template-columns: 15.5rem minmax(0, 1fr);
  min-height: 100dvh;
  background: var(--color-paper);
}

.app-shell.is-rail-collapsed {
  grid-template-columns: 4.25rem minmax(0, 1fr);
}

.app-rail {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-2xs) var(--space-sm) var(--space-xs);
  background: var(--color-paper-2);
  border-right: 1px solid var(--border-subtle);
  min-height: 100dvh;
}

.app-rail-brand {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2xs);
  padding: 0 var(--space-2xs) var(--space-xs);
}

.app-rail-toggle {
  flex: 0 0 auto;
  width: 2rem;
  height: 2rem;
  border: 0;
  border-radius: var(--radius-input);
  background: transparent;
  color: var(--color-ink-2);
  cursor: pointer;
}

.app-rail-toggle:hover {
  background: var(--color-accent-soft);
  color: var(--color-ink);
}

.app-rail-toggle:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.app-rail-nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.app-rail-item {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  min-height: var(--control-height);
  padding: 0 var(--space-xs);
  border-radius: 0.75rem;
  color: var(--color-ink);
  text-decoration: none;
  font-family: var(--font-body);
  font-size: var(--control-font);
  font-weight: 500;
  line-height: var(--control-line);
  border: 0;
  background: transparent;
  cursor: pointer;
  width: 100%;
  text-align: left;
}

.app-rail-item:hover {
  background: color-mix(in srgb, var(--color-accent) 8%, transparent);
}

.app-rail-item:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.app-rail-item.is-active {
  background: var(--color-accent-soft);
  color: var(--color-ink);
  font-weight: 600;
}

.app-rail-icon {
  flex: 0 0 auto;
  width: 1.15rem;
  height: 1.15rem;
}

.app-rail-label {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
}

.app-shell.is-rail-collapsed .app-rail-label,
.app-shell.is-rail-collapsed .app-rail-brand .brand-text {
  display: none;
}

.app-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 100dvh;
  background: var(--color-paper);
}

.app-topbar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--space-xs);
  min-height: 3.5rem;
  padding: var(--space-2xs) var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
}

.app-topbar-actions {
  display: flex;
  align-items: center;
  gap: var(--space-2xs);
}

.app-usage-chip {
  margin-right: auto;
  min-height: var(--control-height);
  padding: 0 var(--control-pad-x);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-pill);
  background: var(--color-paper);
  color: var(--color-ink);
  font-family: var(--font-body);
  font-size: var(--control-font);
  font-weight: 600;
  cursor: pointer;
}

.app-usage-chip:hover {
  border-color: var(--border-hover);
  background: var(--color-paper-2);
}

.app-usage-chip:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

.app-page {
  flex: 1;
  min-width: 0;
  padding: var(--space-md) var(--space-lg) var(--space-xl);
}

.app-page-title {
  margin: 0 0 var(--space-sm);
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 2vw + 1rem, 2rem);
  font-weight: 700;
  font-style: normal;
  letter-spacing: -0.025em;
  color: var(--color-ink);
}

.app-page-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

.app-pane[hidden] {
  display: none;
}

.app-shell .admin-panel {
  background: var(--color-paper);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-card);
  box-shadow: none;
  padding: var(--space-md);
  margin-bottom: var(--space-md);
}

.app-shell .admin-panel-title {
  margin: 0 0 var(--space-xs);
  font-family: var(--font-display);
  font-size: 1.05rem;
  font-weight: 600;
}

.app-shell .admin-table {
  width: 100%;
  border-collapse: collapse;
}

.app-shell .admin-table th {
  text-align: left;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 0.72rem;
  font-weight: 600;
  color: var(--color-muted);
  padding: var(--space-xs) var(--space-sm);
  border-bottom: 1px solid var(--color-rule);
  background: transparent;
}

.app-shell .admin-table td {
  padding: 0.85rem var(--space-sm);
  border-bottom: 1px solid var(--border-subtle);
  vertical-align: middle;
}

.app-shell .admin-header,
.app-shell .app-header {
  display: none;
}

.app-lock {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.1rem 0.4rem;
  border-radius: var(--radius-pill);
  background: color-mix(in srgb, var(--color-status-ochre) 14%, var(--color-paper));
  color: var(--color-status-ochre);
  font-size: 0.65rem;
  font-weight: 600;
}

@media (max-width: 768px) {
  .app-shell,
  .app-shell.is-rail-collapsed {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
  }

  .app-rail {
    flex-direction: row;
    align-items: center;
    min-height: 0;
    height: auto;
    overflow-x: auto;
    border-right: 0;
    border-bottom: 1px solid var(--border-subtle);
    padding: var(--space-2xs) var(--space-xs);
  }

  .app-rail-nav {
    flex-direction: row;
    flex: 1;
  }

  .app-rail-item {
    width: auto;
  }

  .app-rail-label {
    display: none;
  }

  .app-page {
    padding: var(--space-sm) var(--space-sm) var(--space-lg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .app-rail-item,
  .app-usage-chip,
  .app-rail-toggle {
    transition: none;
  }
}

const RAIL_KEY = "kuchup-app-rail-collapsed";
const ADMIN_PANES = ["home", "catalog", "problems", "users", "jobs", "runs", "config"];

export function initAppShell() {
  const shell = document.querySelector(".app-shell");
  const toggle = document.getElementById("appRailToggle");
  if (!shell || !toggle) return;

  const apply = (collapsed) => {
    shell.classList.toggle("is-rail-collapsed", collapsed);
    toggle.setAttribute("aria-expanded", collapsed ? "false" : "true");
    toggle.setAttribute("aria-label", collapsed ? "Expand menu" : "Minimize menu");
  };

  apply(window.localStorage.getItem(RAIL_KEY) === "1");
  toggle.addEventListener("click", () => {
    const next = !shell.classList.contains("is-rail-collapsed");
    apply(next);
    window.localStorage.setItem(RAIL_KEY, next ? "1" : "0");
  });
}

export function showAdminPane(name) {
  const pane = ADMIN_PANES.includes(name) ? name : "home";
  document.querySelectorAll("[data-admin-pane]").forEach((el) => {
    el.hidden = el.dataset.adminPane !== pane;
  });
  document.querySelectorAll("[data-admin-nav]").forEach((el) => {
    el.classList.toggle("is-active", el.dataset.adminNav === pane);
  });
}

export function initAdminPanes() {
  if (!document.querySelector("[data-admin-pane]")) return;
  const fromHash = () => showAdminPane((window.location.hash || "#home").slice(1));
  window.addEventListener("hashchange", fromHash);
  fromHash();
}

