new Promise((resolve)=>{
  const waitShell=()=>{
    const s=document.querySelector('.app-shell');
    if(s && !s.hidden && !s.classList.contains('hidden')){
      const field=document.querySelector('.search-field');
      const icon=document.querySelector('.search-field-icon');
      const input=document.querySelector('#search');
      const css=[...document.styleSheets].map(ss=>ss.href).filter(Boolean);
      const checkLoader=()=>{
        const l=document.getElementById('screenLoader');
        const visible=l && !l.hidden && l.classList.contains('is-visible') && getComputedStyle(l).visibility!=='hidden';
        resolve({
          css,
          fieldH: field?.getBoundingClientRect().height,
          iconT: icon?.getBoundingClientRect().top,
          inputT: input?.getBoundingClientRect().top,
          inputH: input?.getBoundingClientRect().height,
          fieldFlex: field && getComputedStyle(field).flex,
          w: window.innerWidth,
          loaderVisible: !!visible,
          pct: document.getElementById('screenLoaderPct')?.textContent,
        });
      };
      const t0=Date.now();
      const poll=()=>{
        const l=document.getElementById('screenLoader');
        const visible=l && !l.hidden && l.classList.contains('is-visible') && getComputedStyle(l).opacity!=='0';
        if(!visible || Date.now()-t0>25000) checkLoader();
        else setTimeout(poll,200);
      };
      poll();
      return;
    }
    setTimeout(waitShell,100);
  };
  waitShell();
  setTimeout(()=>resolve({timeout:true,w:window.innerWidth}),30000);
})

