export function endScreenLoad() {
  if (depth === 0) return;
  depth = 0;

  bumpTarget(100);
  startLoop();

  const { root } = elements();
  if (!root) return;

  const finalize = () => {
    root.classList.add("is-done");
    root.classList.remove("is-visible");
    document.body.classList.remove("screen-loading");
    finishTimer = window.setTimeout(() => {
      if (depth === 0) {
        root.hidden = true;
        root.classList.remove("is-done");
        resetSession();
      }
      finishTimer = null;
    }, 400);
  };

  const waitComplete = () => {
    if (displayPct >= 99.5) {
      finalize();
      return;
    }
    requestAnimationFrame(waitComplete);
  };
  waitComplete();
}

input.new_string:
export function endScreenLoad() {
  if (depth === 0) return;
  depth = 0;
  stopLoop();

  const { root } = elements();
  if (!root) return;
  root.classList.add("is-done");
  root.classList.remove("is-visible");
  document.body.classList.remove("screen-loading");
  if (finishTimer) clearTimeout(finishTimer);
  finishTimer = window.setTimeout(() => {
    root.hidden = true;
    root.classList.remove("is-done");
    resetSession();
    finishTimer = null;
  }, 400);
}

