params.expression:
(() => {
  const btn = document.querySelector('.looking-to-apply-btn.active');
  const row = btn?.closest('.position-actions-primary');
  const more = row?.querySelector('.position-more-btn');
  const card = btn?.closest('.position-card');
  const r = (el) => el ? el.getBoundingClientRect().toJSON() : null;
  return {
    text: btn?.textContent?.trim() || null,
    btn: r(btn),
    more: r(more),
    row: r(row),
    card: r(card),
    overflow: card ? card.scrollWidth > card.clientWidth + 1 : null,
    rowOverflow: row ? row.scrollWidth > row.clientWidth + 1 : null,
    lookingTop: btn && row ? Math.round(btn.getBoundingClientRect().top - row.getBoundingClientRect().top) : null,
  };
})()
